-- Native source, qualification and owner-selected installs; setup only.
create function pg_temp.spr_assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'Package read-only setup: %',label; end if; end $$;
create function pg_temp.spr_expect(q text,expected text) returns void language plpgsql as $$ begin begin execute q; exception when others then if position(expected in sqlerrm)>0 then return; end if; raise; end; raise exception 'Expected %',expected; end $$;
