create temporary table spr_source(id uuid);
insert into spr_source select (public.create_system_version_source('d7100000-0000-4000-8000-000000000010','d7100000-0000-4000-8000-000000000001','readonly-package-creator@example.test','{"name":"Shared intake","kind":"internal_app"}','d7100000-0000-4000-8000-000000000020',repeat('a',64))->'system'->>'id')::uuid;
create function pg_temp.spr_definition() returns jsonb language sql as $$ select '{"kind":"internal_app","title":"Client intake","fields":[{"id":"problem","label":"Problem","type":"text","required":true}],"components":[{"kind":"form","fields":["problem"]},{"kind":"list","fields":["problem"]}]}'::jsonb $$;
create function pg_temp.spr_revision(n integer) returns jsonb language sql as $$ select jsonb_build_object('source',jsonb_build_object('businessId','d7100000-0000-4000-8000-000000000010','systemId',(select id from spr_source),'revisionId',('d7100000-0000-4000-8000-'||lpad((20+n)::text,12,'0'))::uuid,'number',n),'definition',case when n=1 then pg_temp.spr_definition() else jsonb_set(pg_temp.spr_definition(),'{title}',to_jsonb('Updated intake'::text)) end,'declaration',public.system_package_behavior(pg_temp.spr_definition(),'{}'::text[]),'summary','Qualified native intake','requires','{"bindingKinds":[]}'::jsonb,'publishedBy','d7100000-0000-4000-8000-000000000001','publishedAt',now()) $$;
select public.publish_system_version_source_revision('d7100000-0000-4000-8000-000000000001','readonly-package-creator@example.test',pg_temp.spr_revision(1));
select pg_temp.spr_assert(not public.system_revision_is_qualified('d7100000-0000-4000-8000-000000000021'),'publication is not qualification');
select public.record_system_revision_qualification('d7100000-0000-4000-8000-000000000001','readonly-package-creator@example.test','d7100000-0000-4000-8000-000000000021');
select pg_temp.spr_expect($q$select public.review_system_revision_qualification('d7100000-0000-4000-8000-000000000003','readonly-package-reviewer@example.test','d7100000-0000-4000-8000-000000000021',true,'Review')$q$,'system_revision_reviewer_policy_required');
-- Fixture-only review policy. No application seed installs a default reviewer.
insert into public.system_revision_reviewers(user_id,policy_version) values('d7100000-0000-4000-8000-000000000003','fictional-local-test-policy');
select public.review_system_revision_qualification('d7100000-0000-4000-8000-000000000003','readonly-package-reviewer@example.test','d7100000-0000-4000-8000-000000000021',true,'Reviewed exact immutable definition and declaration');
select pg_temp.spr_assert(public.system_revision_is_qualified('d7100000-0000-4000-8000-000000000021'),'passing checks plus exact human approval qualifies');
select public.set_system_package_listing('d7100000-0000-4000-8000-000000000010','d7100000-0000-4000-8000-000000000001','readonly-package-creator@example.test',(select id from spr_source),'listed');
select pg_temp.spr_assert(jsonb_array_length(public.read_system_package_listings('d7100000-0000-4000-8000-000000000011','d7100000-0000-4000-8000-000000000002','readonly-package-owner@example.test'))=1,'ordinary owner sees qualified independent creator listing');
select pg_temp.spr_expect($q$select public.system_package_assert_declaration(pg_temp.spr_definition(),'{"recordsRead":[],"recordsWritten":[],"businessRecordFields":[],"outsideEffects":[],"bindingKinds":[],"dataLeavingBusiness":[]}','{}')$q$,'system_package_declaration_exceeded');
select pg_temp.spr_expect($q$update public.system_version_sources set creator_workspace_id='d7100000-0000-4000-8000-000000000011' where system_id=(select id from spr_source)$q$,'system_version_identity_immutable');

create function pg_temp.spr_lineage(command uuid,actor uuid,business uuid) returns jsonb language sql as $$ select jsonb_build_object('id',gen_random_uuid(),'version',jsonb_build_object('businessId',business,'systemId',command),'source',jsonb_build_object('businessId','d7100000-0000-4000-8000-000000000010','systemId',(select id from spr_source)),'context','{"kind":"agency_client","label":"Owner intake"}'::jsonb,'baseline',jsonb_build_object('revision',1,'definition',pg_temp.spr_definition()),'overrides','[]'::jsonb,'bindings','[]'::jsonb,'localData','{}'::jsonb,'releases','[]'::jsonb,'currentRelease',null,'decisions','[]'::jsonb,'grants','[]'::jsonb,'rowRevision',1,'createdBy',actor,'createdAt',now(),'updatedAt',now()) $$;
create function pg_temp.spr_payload(actor uuid) returns jsonb language sql as $$ select jsonb_build_object('version',1,'revision',0,'title','Client intake','createdBy',actor,'createdAt',now(),'history','[]'::jsonb,'spec',(pg_temp.spr_definition()-'kind')||jsonb_build_object('maintenanceOwner',actor),'specVersion',1,'status','draft','versions',jsonb_build_array(jsonb_build_object('version',1,'spec',(pg_temp.spr_definition()-'kind')||jsonb_build_object('maintenanceOwner',actor))),'rehearsal',null,'records','[]'::jsonb) $$;
create temporary table spr_created(value jsonb);
insert into spr_created select public.create_version_system_command('d7100000-0000-4000-8000-000000000002','readonly-package-owner@example.test',pg_temp.spr_lineage('d7100000-0000-4000-8000-000000000030','d7100000-0000-4000-8000-000000000002','d7100000-0000-4000-8000-000000000011'),'Client intake','internal_app','d7100000-0000-4000-8000-000000000030',pg_temp.spr_payload('d7100000-0000-4000-8000-000000000002'));
select pg_temp.spr_assert((select value->>'creatorWorkspaceId'='d7100000-0000-4000-8000-000000000010' and value->>'sourceRevisionId'='d7100000-0000-4000-8000-000000000021' and value->'currentRelease'='null'::jsonb from spr_created),'owner installation freezes creator and exact revision; draft does not go live');
select pg_temp.spr_assert(public.create_version_system_command('d7100000-0000-4000-8000-000000000002','readonly-package-owner@example.test',pg_temp.spr_lineage('d7100000-0000-4000-8000-000000000030','d7100000-0000-4000-8000-000000000002','d7100000-0000-4000-8000-000000000011'),'Client intake','internal_app','d7100000-0000-4000-8000-000000000030',pg_temp.spr_payload('d7100000-0000-4000-8000-000000000002'))->>'id'=(select value->>'id' from spr_created),'retry returns the same real System/Version');
select pg_temp.spr_expect($q$select public.create_version_system_command('d7100000-0000-4000-8000-000000000001','readonly-package-creator@example.test',pg_temp.spr_lineage('d7100000-0000-4000-8000-000000000031','d7100000-0000-4000-8000-000000000001','d7100000-0000-4000-8000-000000000011'),'Client intake','internal_app','d7100000-0000-4000-8000-000000000031',pg_temp.spr_payload('d7100000-0000-4000-8000-000000000001'))$q$,'business_record_access_denied');
